      if (!cur) break;
      const curKey = xyKey(cur.x, cur.y);
      if (fallbackClosed.has(curKey)) continue;
      fallbackClosed.add(curKey);
      if (curKey === targetKey) {
        pathFound = true;
        break;
      }
      for (const [dx, dy] of dirs4) {
        const nx = cur.x + dx;
        const ny = cur.y + dy;
