// Stamps a JSON building definition onto the chunk map at a given anchor position.

import {
  TILE_FLOOR,
  TILE_WALL,
  TILE_DOOR,
  TILE_GRASS,
  TILE_GRASS_A,
  TILE_GRASS_C,
  TILE_GRASS_D,
